1	export type QuoteResult = { premium: number };
2	
3	export type ClaimResult = { payout: number; remainingCap: number };
4	
5	export type StepResult = QuoteResult | ClaimResult;
6	
7	export type ScenarioResults = { results: StepResult[] };
8	
9	const PROCESSING_FEE = 5;
10	
11	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
12	
13	const LOYALTY_DISCOUNT_RATE = 0.2;
14	
15	const LOYALTY_THRESHOLD_YEARS = 2;
16	
17	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
18	
19	// One catalogue entry per insurable item type. Premium and insurance value are
20	// two facts about the same thing, so they live together: an item type either is
21	// in the catalogue with both, or is unknown.
22	type CatalogueEntry = { basePremium: number; insuranceValue: number };
23	
24	const ITEM_CATALOGUE: Record<string, CatalogueEntry> = {
25	  sword: { basePremium: 100, insuranceValue: 1000 },
26	  amulet: { basePremium: 60, insuranceValue: 600 },
27	  staff: { basePremium: 80, insuranceValue: 800 },
28	  potion: { basePremium: 40, insuranceValue: 400 },
29	  rune: { basePremium: 25, insuranceValue: 250 },
30	  moonstone: { basePremium: 25, insuranceValue: 250 },
31	};
32	
33	const basePremiumOf = (type: string): number =>
34	  ITEM_CATALOGUE[type].basePremium;
35	
36	const insuranceValueOf = (type: string): number =>
37	  ITEM_CATALOGUE[type].insuranceValue;
38	
39	type Item = { type: string; cursed?: boolean; enchantment?: number };
40	
41	// Steps are discriminated by `op`: a quote carries the items to insure, a claim
42	// carries damage entries against a policy an earlier quote step created.
43	type QuoteStep = { op: "quote"; items: Item[] };
44	
45	type Damage = { itemType: string; amount: number };
46	
47	type Incident = { cause: string; damages: Damage[] };
48	
49	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
50	
51	type Step = QuoteStep | ClaimStep;
52	
53	// Scenarios arrive as parsed JSON (from the CLI, and from object literals in
54	// the spec whose `op` widens to `string`), so the boundary type is deliberately
55	// wider than `Step`. Narrowing happens once, in `runStep`.
56	type StepInput = {
57	  op: string;
58	  items?: Item[];
59	  policy?: number;
60	  incident?: Incident;
61	};
62	
63	const isQuoteStep = (step: StepInput): step is QuoteStep =>
64	  step.op === "quote" && step.items !== undefined;
65	
66	const isClaimStep = (step: StepInput): step is ClaimStep =>
67	  step.op === "claim" && step.incident !== undefined && step.policy !== undefined;
68	
69	type Customer = { yearsWithMHPCO: number };
70	
71	type Scenario = { customer: Customer; steps: StepInput[] };
72	
73	const BLOCK_SIZE = 3;
74	
75	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
76	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
77	// a block either — "alike" means the same type, not the same family.
78	const BLOCK_BASE_PREMIUM = 60;
79	
80	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
81	
82	const countByType = (items: Item[]): Map<string, number> =>
83	  items.reduce(
84	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
85	    new Map<string, number>(),
86	  );
87	
88	const isBlock = (type: string, count: number): boolean =>
89	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
90	
91	const groupBasePremium = (type: string, count: number): number =>
92	  isBlock(type, count) ? BLOCK_BASE_PREMIUM : count * basePremiumOf(type);
93	
94	const sum = (numbers: number[]): number =>
95	  numbers.reduce((total, value) => total + value, 0);
96	
97	const policyBasePremium = (items: Item[]): number =>
98	  sum(
99	    [...countByType(items)].map(([type, count]) =>
100	      groupBasePremium(type, count),
101	    ),
102	  );
103	
104	const CURSE_SURCHARGE_RATE = 0.5;
105	
106	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
107	
108	const HIGH_ENCHANTMENT_THRESHOLD = 5;
109	
110	const isCursed = (item: Item): boolean => item.cursed === true;
111	
112	const isHighlyEnchanted = (item: Item): boolean =>
113	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
114	
115	// Both surcharges can apply to the same item, so the rates add.
116	const itemSurchargeRate = (item: Item): number =>
117	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
118	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
119	
120	// Item-specific modifiers apply to the affected item's own base premium, not to
121	// the policy total — note that is the *ungrouped* base premium, so a cursed
122	// rune inside a block is surcharged on 25 G, not on a share of the block's 60.
123	const policyItemSurchargeTotal = (items: Item[]): number =>
124	  sum(
125	    items.map((item) => basePremiumOf(item.type) * itemSurchargeRate(item)),
126	  );
127	
128	const isLoyal = (customer: Customer): boolean =>
129	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
130	
131	// Policy-wide rates are summed rather than compounded, so a loyal customer's
132	// first insurance is levied at -20 % + 10 % = -10 % of the policy base premium.
133	// Every quote after the customer's first is a follow-up contract; the
134	// first-insurance surcharge still applies to it, since each item in a quote is
135	// treated as a first insurance regardless of customer history.
136	const policyModifierRate = (customer: Customer, isFollowUp: boolean): number =>
137	  (isLoyal(customer) ? -LOYALTY_DISCOUNT_RATE : 0) +
138	  (isFollowUp ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0) +
139	  FIRST_INSURANCE_SURCHARGE_RATE;
140	
141	const priceQuote = (
142	  step: QuoteStep,
143	  customer: Customer,
144	  isFollowUp: boolean,
145	): QuoteResult => {
146	  // Every modifier is a percentage of an *unmodified* base and they are all
147	  // summed, never compounded. Item surcharges are percentages of the affected
148	  // item's own base premium; policy-wide modifiers are percentages of the
149	  // policy base premium, which excludes those item surcharges. Summing the
150	  // rates before multiplying also keeps binary floating point out of trouble:
151	  // a compounded `base * (1 + rate)` chain drifts by ~1e-14, and Math.ceil
152	  // would turn that into a whole extra gold piece.
153	  const policyBase = policyBasePremium(step.items);
154	  const premiumBeforeFee =
155	    policyBase +
156	    policyItemSurchargeTotal(step.items) +
157	    policyBase * policyModifierRate(customer, isFollowUp);
158	
159	  // The fee is added after every percentage modifier, and only the final
160	  // premium is rounded — intermediates stay fractional.
161	  return { premium: Math.ceil(premiumBeforeFee + PROCESSING_FEE) };
162	};
163	
164	// A quote is a follow-up contract when the customer already holds one, i.e.
165	// when an earlier step in this scenario was itself a quote. Preceding claim
166	// steps do not make the next quote a follow-up.
167	const isFollowUpContract = (steps: StepInput[], index: number): boolean =>
168	  steps.slice(0, index).some(isQuoteStep);
169	
170	const DEDUCTIBLE_PER_DAMAGE = 100;
171	
172	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
173	
174	// The insurance sum is the plain sum of the items' insurance values; the block
175	// discount applies to the premium only, never to the sum insured.
176	const insuranceSum = (items: Item[]): number =>
177	  sum(items.map((item) => insuranceValueOf(item.type)));
178	
179	// A policy pays out at most twice its insurance sum over its lifetime.
180	const policyCap = (items: Item[]): number =>
181	  CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(items);
182	
183	// Distinct from the premium-side threshold of 5: this is a different rule that
184	// happens to key off the same item attribute.
185	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
186	
187	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
188	
189	const isHighlyEnchantedForClaims = (item: Item | undefined): boolean =>
190	  (item?.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
191	
192	// A reimbursement clause reduces the damage amount; the deductible comes off
193	// whatever the clause leaves.
194	const damagePayout = (damage: Damage, item: Item | undefined): number => {
195	  const reimbursed = isHighlyEnchantedForClaims(item)
196	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
197	    : damage.amount;
198	
199	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
200	};
201	
202	// The deductible applies once per damaged item, so each damage entry is
203	// reduced separately before the entries are summed. A damage entry names its
204	// item by type, so the clauses are read off the matching insured item.
205	const incidentPayout = (incident: Incident, policyItems: Item[]): number =>
206	  Math.floor(
207	    sum(
208	      incident.damages.map((damage) =>
209	        damagePayout(
210	          damage,
211	          policyItems.find((item) => item.type === damage.itemType),
212	        ),
213	      ),
214	    ),
215	  );
216	
217	const settleClaim = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
218	  const payout = incidentPayout(step.incident, policyItems);
219	
220	  return { payout, remainingCap: policyCap(policyItems) - payout };
221	};
222	
223	const quoteStepAt = (steps: StepInput[], index: number): QuoteStep => {
224	  // `policy` is a step number in the scenario, so it indexes the full step
225	  // list — not a prefix of it.
226	  const step = steps[index];
227	  if (step === undefined || !isQuoteStep(step)) {
228	    throw new Error(`Claim references a step that is not a quote`);
229	  }
230	  return step;
231	};
232	
233	const runStep = (
234	  step: StepInput,
235	  customer: Customer,
236	  steps: StepInput[],
237	  index: number,
238	): StepResult => {
239	  if (isQuoteStep(step)) {
240	    return priceQuote(step, customer, isFollowUpContract(steps, index));
241	  }
242	  if (isClaimStep(step)) {
243	    return settleClaim(step, quoteStepAt(steps, step.policy).items);
244	  }
245	  throw new Error(`Unsupported step op: ${step.op}`);
246	};
247	
248	export const runScenario = (scenario: Scenario): ScenarioResults => ({
249	  results: scenario.steps.map((step, index) =>
250	    runStep(step, scenario.customer, scenario.steps, index),
251	  ),
252	});
