// Distinct from the premium-side high-enchantment *surcharge*, whose threshold
// is 5: this is a different rule that happens to key off the same attribute.
const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;

const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

const FULL_REIMBURSEMENT_RATE = 1;

const hasHighEnchantmentReimbursement = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD;

// Each clause states the share of the damage it will reimburse. When several
// clauses apply, the most restrictive one governs — so the applicable rate is
// the lowest, and an item that trips no clause is reimbursed in full.
const reimbursementRate = (item: Item): number =>
  Math.min(
    FULL_REIMBURSEMENT_RATE,
    ...(hasHighEnchantmentReimbursement(item)
      ? [HIGH_ENCHANTMENT_REIMBURSEMENT_RATE]
      : []),
  );

// A reimbursement clause reduces the damage amount; the deductible comes off
// whatever the clause leaves.
//
// `item` is optional only because a damage entry naming an uninsured item is
// not yet rejected — that is a pending error test. Until then such an entry is
// reimbursed in full, and this is the single place tolerating the gap.
const damagePayout = (damage: Damage, item: Item | undefined): number => {
  const rate = item === undefined ? FULL_REIMBURSEMENT_RATE : reimbursementRate(item);

  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
};

